import type { LevelDef, Mode } from "../core/types";
import { DESTINATION } from "./destination";
import { COLLECT } from "./collect";
import { SEQUENCE } from "./sequence";
import { SURVIVAL } from "./survival";
import { WAVES } from "./waves";
import { t } from "../i18n";

// ---------------------------------------------------------------------------
// LEVELS — 20 per mode, one file per mode (destination.ts, collect.ts, ...). They are
// generated by tools/gen-levels.ts on a rising difficulty curve, each with a proof that it can
// be beaten; tests/levels.test.ts replays every proof. Map legend: core/types.ts (LevelDef.map).
// Coordinates in sentry paths and drops are "x,y" from the top-left, starting at 0.
// ---------------------------------------------------------------------------

export interface ModeInfo {
  id: Mode;
  /** the text is in the current language: i18n/en.ts has the English */
  name: string;
  /** one line, for lists */
  blurb: string;
  /** a few sentences for the mode screen */
  about: string;
  /** the level shown, hazards running, as the mode's preview */
  preview: string;
  /** still being designed */
  wip?: boolean;
  /** the mode played as a co-op team: its one-line blurb and its rule */
  coop: { blurb: string; about: string };
}

/** a mode, its text in the current language (i18n: mode.<id>...) */
function mode(id: Mode, preview: string, wip?: boolean): ModeInfo {
  return {
    id, preview, wip,
    get name(){ return t(`mode.${id}`); },
    get blurb(){ return t(`mode.${id}.blurb`); },
    get about(){ return t(`mode.${id}.about`); },
    coop: {
      get blurb(){ return t(`mode.${id}.coopBlurb`); },
      get about(){ return t(`mode.${id}.coopAbout`); },
    },
  };
}

export const MODES: ModeInfo[] = [
  mode("destination", "d14"),
  mode("collect", "c10"),
  mode("sequence", "s10"),
  mode("survival", "r13"),
  mode("waves", "w6", true),
];

export const LEVELS: LevelDef[] = [...DESTINATION, ...COLLECT, ...SEQUENCE, ...SURVIVAL, ...WAVES];

export function levelsOf(mode: Mode): LevelDef[] { return LEVELS.filter(l => l.mode === mode); }
export function levelById(id: string): LevelDef | undefined { return LEVELS.find(l => l.id === id); }
